import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { computeRanges, parseStrykerReport, runMutate } from "../src/mutate.ts";

function tmpRepo(withConfig = true): { dir: string; cleanup: () => void } {
	const dir = mkdtempSync(join(tmpdir(), "craft-mutate-"));
	if (withConfig) writeFileSync(join(dir, "stryker.config.json"), "{}");
	return { dir, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

function writeReport(dir: string, report: unknown): void {
	mkdirSync(join(dir, "reports", "mutation"), { recursive: true });
	writeFileSync(join(dir, "reports", "mutation", "mutation.json"), JSON.stringify(report));
}

const DIFF = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,2 +10,3 @@", "+x"].join("\n");

test("skips silently when the repo has no stryker config", () => {
	const { dir, cleanup } = tmpRepo(false);
	try {
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "no-backend");
	} finally {
		cleanup();
	}
});

test("skips when the diff touches no source lines", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const testOnly = ["--- a/test/a.test.ts", "+++ b/test/a.test.ts", "@@ -1,0 +2,3 @@", "+x"].join("\n");
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => testOnly, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "no-changes");
	} finally {
		cleanup();
	}
});

test("skips an oversize diff without running anything", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		let ran = false;
		const big = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,5000 @@"].join("\n");
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			maxLines: 2000,
			gitDiff: () => big,
			runStryker: () => {
				ran = true;
				return { ok: true, timedOut: false };
			},
		});
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "oversize");
		assert.equal(r.lines_scoped, 5000);
		assert.equal(ran, false, "must not invoke the backend for an oversize diff");
	} finally {
		cleanup();
	}
});

test("reports a timeout as skipped rather than an error", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => DIFF,
			runStryker: () => ({ ok: false, timedOut: true }),
		});
		assert.equal(r.status, "skipped");
		assert.equal(r.reason, "timeout");
	} finally {
		cleanup();
	}
});

test("errors when the backend ran but produced no report", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => DIFF,
			runStryker: () => ({ ok: false, timedOut: false, detail: "boom" }),
		});
		assert.equal(r.status, "error");
		assert.equal(r.reason, "failed");
	} finally {
		cleanup();
	}
});

test("parses a real report shape into counts and survivors", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, {
			files: {
				"src/a.ts": {
					mutants: [
						{ mutatorName: "ConditionalExpression", replacement: "false", status: "Killed", coveredBy: ["0"], location: { start: { line: 12 } } },
						{ mutatorName: "StringLiteral", replacement: '""', status: "Survived", coveredBy: ["0"], location: { start: { line: 59 } } },
						{ mutatorName: "BlockStatement", replacement: "{}", status: "NoCoverage", location: { start: { line: 80 } } },
						{ mutatorName: "ArithmeticOperator", replacement: "-", status: "Timeout", coveredBy: ["0"], location: { start: { line: 90 } } },
					],
				},
			},
			testFiles: { "test/a.test.ts": { tests: [{ id: "0", name: "does a thing" }] } },
		});
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		assert.equal(r.status, "ran");
		assert.equal(r.backend, "stryker");
		assert.equal(r.tested, 4);
		assert.equal(r.killed, 2, "a timeout counts as killed — behaviour changed detectably");
		assert.equal(r.survived, 1);
		assert.equal(r.no_coverage, 1);
		assert.deepEqual(r.survivors, [
			{ file: "src/a.ts", line: 59, mutator: "StringLiteral", replacement: '""', covered_by: ["test/a.test.ts"] },
		]);
	} finally {
		cleanup();
	}
});

test("statuses that say nothing about test quality are excluded from the count", () => {
	const parsed = parseStrykerReport({
		files: {
			"src/a.ts": {
				mutants: [
					{ mutatorName: "M", replacement: "x", status: "CompileError", location: { start: { line: 1 } } },
					{ mutatorName: "M", replacement: "x", status: "Ignored", location: { start: { line: 2 } } },
					{ mutatorName: "M", replacement: "x", status: "Killed", location: { start: { line: 3 } } },
				],
			},
		},
	});
	assert.equal(parsed.tested, 1);
	assert.equal(parsed.killed, 1);
});

test("a survivor nothing covered reports an empty test list, not a missing field", () => {
	const parsed = parseStrykerReport({
		files: { "src/a.ts": { mutants: [{ mutatorName: "M", replacement: "x", status: "Survived", location: { start: { line: 5 } } }] } },
	});
	assert.deepEqual(parsed.survivors[0].covered_by, []);
});

test("computeRanges merges and filters end to end", () => {
	const diff = [
		"--- a/src/a.ts",
		"+++ b/src/a.ts",
		"@@ -1,0 +10,2 @@",
		"+x",
		"@@ -1,0 +12,2 @@",
		"+y",
		"--- a/test/a.test.ts",
		"+++ b/test/a.test.ts",
		"@@ -1,0 +1,9 @@",
		"+z",
	].join("\n");
	assert.deepEqual(computeRanges(diff), [{ file: "src/a.ts", start: 10, end: 13 }]);
});

test("an untracked source file is scoped in full — git diff cannot see it", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, { files: {}, testFiles: {} });
		let mutateArgs: string[] = [];
		const r = runMutate({
			cwd: dir,
			base: "HEAD",
			gitDiff: () => "", // a brand-new file produces no diff output at all
			untracked: () => [
				{ file: "src/brand-new.ts", lines: 40 },
				{ file: "test/brand-new.test.ts", lines: 20 }, // excluded: it is a test
				{ file: "README.md", lines: 10 }, // excluded: not source
			],
			runStryker: (_d, args) => {
				mutateArgs = args;
				return { ok: true, timedOut: false };
			},
		});
		assert.equal(r.status, "ran");
		assert.equal(r.lines_scoped, 40);
		assert.deepEqual(mutateArgs, ["src/brand-new.ts:1:1-41:1"]);
	} finally {
		cleanup();
	}
});

test("an empty untracked file scopes nothing rather than an invalid range", () => {
	assert.deepEqual(computeRanges("", [{ file: "src/empty.ts", lines: 0 }]), []);
});

test("tracked edits and new files combine into one scope", () => {
	const ranges = computeRanges(DIFF, [{ file: "src/new.ts", lines: 5 }]);
	assert.deepEqual(ranges, [
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/new.ts", start: 1, end: 5 },
	]);
});

// --- gaps found by mutation testing, not by review ---

test("a diff exactly at the line cap runs; one line over is skipped", () => {
	// `>` vs `>=` at the boundary. Nothing previously tested the exact limit, so
	// the off-by-one was invisible.
	const at = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,100 @@"].join("\n");
	const over = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +1,101 @@"].join("\n");
	for (const [diff, expected] of [
		[at, "ran"],
		[over, "skipped"],
	] as const) {
		const { dir, cleanup } = tmpRepo();
		try {
			writeReport(dir, { files: {}, testFiles: {} });
			const r = runMutate({
				cwd: dir,
				base: "HEAD",
				maxLines: 100,
				gitDiff: () => diff,
				runStryker: () => ({ ok: true, timedOut: false }),
			});
			assert.equal(r.status, expected, `${r.lines_scoped} lines against a cap of 100`);
		} finally {
			cleanup();
		}
	}
});

test("the default excludes drop a test file that lives under src/", () => {
	// The end-to-end fixture used `test/a.test.ts`, which DEFAULT_INCLUDE rejects on
	// its own — so DEFAULT_EXCLUDE was never actually exercised. A test file inside
	// src/ passes the include and can only be dropped by the exclude.
	assert.deepEqual(computeRanges(["--- a/src/a.test.ts", "+++ b/src/a.test.ts", "@@ -1,0 +1,9 @@"].join("\n")), []);
	assert.deepEqual(computeRanges(["--- a/src/a.spec.ts", "+++ b/src/a.spec.ts", "@@ -1,0 +1,9 @@"].join("\n")), []);
});

test("duration is measured forward, not backward", () => {
	const { dir, cleanup } = tmpRepo();
	try {
		writeReport(dir, { files: {}, testFiles: {} });
		const r = runMutate({ cwd: dir, base: "HEAD", gitDiff: () => DIFF, runStryker: () => ({ ok: true, timedOut: false }) });
		// `>= 0` alone proves nothing: adding the two timestamps instead of
		// subtracting them also clears zero. An upper bound is what makes this an
		// assertion about an interval rather than about a number being positive.
		assert.ok(r.duration_ms !== undefined, "duration must be reported");
		assert.ok(r.duration_ms! >= 0 && r.duration_ms! < 60_000, `elapsed ms out of range: ${r.duration_ms}`);
	} finally {
		cleanup();
	}
});

test("a survivor covered by an unknown test id reports no test file rather than undefined", () => {
	const parsed = parseStrykerReport({
		files: { "src/a.ts": { mutants: [{ mutatorName: "M", replacement: "x", status: "Survived", coveredBy: ["99"], location: { start: { line: 5 } } }] } },
		testFiles: { "test/a.test.ts": { tests: [{ id: "0" }] } },
	});
	assert.deepEqual(parsed.survivors[0].covered_by, []);
});

test/mutate-cli.test.ts.source:
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { main, run, numFlag, type MutateIo } from "../src/mutate-cli.ts";
import { makeGitDiff, makeRunStryker, makeUntracked, type Exec, type ExecResult } from "../src/mutate-shell.ts";

const OK: ExecResult = { status: 0, stdout: "", stderr: "" };

function harness(opts: { withConfig?: boolean; exec?: Exec; files?: Record<string, string> } = {}) {
	const dir = mkdtempSync(join(tmpdir(), "craft-mutate-cli-"));
	if (opts.withConfig !== false) writeFileSync(join(dir, "stryker.config.json"), "{}");
	const out: string[] = [];
	const err: string[] = [];
	const io: MutateIo = {
		write: (s) => out.push(s),
		error: (s) => err.push(s),
		cwd: () => dir,
		exec: opts.exec ?? (() => OK),
		readFile: (p) => {
			const key = Object.keys(opts.files ?? {}).find((k) => p.endsWith(k));
			if (key === undefined) throw new Error(`no such file: ${p}`);
			return opts.files![key];
		},
	};
	return {
		io,
		dir,
		out: () => out.join(""),
		err: () => err.join(""),
		json: () => JSON.parse(out.join("")),
		cleanup: () => rmSync(dir, { recursive: true, force: true }),
	};
}

test("--help prints usage and succeeds", () => {
	const h = harness();
	try {
		assert.equal(main(["--help"], h.io), 0);
		assert.match(h.out(), /^craft-mutate —/);
	} finally {
		h.cleanup();
	}
});

test("a missing --base exits 2 rather than diffing against nothing", () => {
	const h = harness();
	try {
		assert.equal(main([], h.io), 2);
		assert.match(h.err(), /missing --base/);
	} finally {
		h.cleanup();
	}
});

test("a repo with no stryker config skips and still exits 0", () => {
	const h = harness({ withConfig: false });
	try {
		assert.equal(main(["--base", "HEAD"], h.io), 0, "no backend is not a failure");
		assert.deepEqual(h.json(), { status: "skipped", reason: "no-backend" });
	} finally {
		h.cleanup();
	}
});

test("an unparseable numeric flag is rejected, not silently defaulted", () => {
	for (const flag of ["--timeout", "--max-lines"]) {
		const h = harness();
		try {
			assert.equal(run(["--base", "HEAD", flag, "abc"], h.io), 2, flag);
			assert.match(h.err(), new RegExp(`invalid ${flag} abc`));
		} finally {
			h.cleanup();
		}
	}
});

test("a non-positive numeric flag is rejected", () => {
	const h = harness();
	try {
		assert.equal(run(["--base", "HEAD", "--timeout", "0"], h.io), 2);
	} finally {
		h.cleanup();
	}
});

test("an absent numeric flag falls back without complaint", () => {
	const h = harness();
	try {
		assert.equal(numFlag("--timeout", ["--base", "HEAD"], 60, h.io), 60);
		assert.equal(h.err(), "");
	} finally {
		h.cleanup();
	}
});

test("a failing git diff exits 1 rather than reporting no changes", () => {
	// The dangerous failure: an unresolvable base scoping nothing is
	// indistinguishable from a clean diff unless it is treated as fatal.
	const exec: Exec = (cmd, args) =>
		cmd === "git" && args[0] === "diff"
			? { status: 128, stdout: "", stderr: "fatal: bad revision 'nope'" }
			: OK;
	const h = harness({ exec });
	try {
		assert.equal(run(["--base", "nope"], h.io), 1);
		assert.match(h.err(), /bad revision/);
	} finally {
		h.cleanup();
	}
});

test("the shell adapters compose into a scoped stryker invocation", () => {
	const calls: Array<{ cmd: string; args: string[] }> = [];
	const exec: Exec = (cmd, args) => {
		calls.push({ cmd, args });
		if (cmd === "git" && args[0] === "diff") {
			return { status: 0, stdout: ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -1,0 +10,3 @@", "+x"].join("\n"), stderr: "" };
		}
		return OK;
	};
	const h = harness({ exec });
	try {
		// Stryker writes no report here, so the run reports an error — the point is
		// the arguments it was invoked with.
		run(["--base", "main"], h.io);
		const stryker = calls.find((c) => c.cmd === "npx");
		assert.ok(stryker, "stryker must be invoked");
		assert.deepEqual(stryker!.args, ["stryker", "run", "--mutate", "src/a.ts:10:1-13:1", "--reporters", "json"]);
	} finally {
		h.cleanup();
	}
});

// --- shell adapters, unit level ---

test("git diff failure calls fail rather than returning empty", () => {
	let failed = "";
	const gitDiff = makeGitDiff(() => ({ status: 1, stdout: "", stderr: "boom" }), (m) => {
		failed = m;
		throw new Error("failed");
	});
	assert.throws(() => gitDiff("/tmp", "HEAD"));
	assert.equal(failed, "boom");
});

test("git diff with an empty stderr still reports which ref failed", () => {
	let failed = "";
	const gitDiff = makeGitDiff(() => ({ status: 1, stdout: "", stderr: "   " }), (m) => {
		failed = m;
		throw new Error("failed");
	});
	assert.throws(() => gitDiff("/tmp", "deadbeef"));
	assert.match(failed, /deadbeef/);
});

test("untracked counts lines per file and drops unreadable ones", () => {
	const untracked = makeUntracked(
		() => ({ status: 0, stdout: "src/a.ts\nsrc/gone.ts\n\n  src/b.ts  \n", stderr: "" }),
		(p) => {
			if (p.endsWith("gone.ts")) throw new Error("ENOENT");
			return p.endsWith("a.ts") ? "one\ntwo\nthree" : "solo";
		},
		(a, b) => `${a}/${b}`,
	);
	assert.deepEqual(untracked("/repo"), [
		{ file: "src/a.ts", lines: 3 },
		{ file: "src/gone.ts", lines: 0 },
		{ file: "src/b.ts", lines: 1 },
	]);
});

test("untracked treats a non-repo as having nothing untracked", () => {
	const untracked = makeUntracked(() => ({ status: 128, stdout: "", stderr: "not a git repo" }), () => "", (a, b) => `${a}/${b}`);
	assert.deepEqual(untracked("/tmp"), []);
});

test("a timeout is detected from ETIMEDOUT or a kill signal, not from exit status", () => {
	// All three shapes mean "we ran out of time", and none of them is a nonzero
	// status — treating them as ordinary failures would report a broken run.
	for (const result of [
		{ status: null, stdout: "", stderr: "", error: { code: "ETIMEDOUT" } },
		{ status: null, stdout: "", stderr: "", signal: "SIGTERM" },
		{ status: null, stdout: "", stderr: "", signal: "SIGKILL" },
	] as ExecResult[]) {
		const outcome = makeRunStryker(() => result)("/repo", ["src/a.ts:1:1-2:1"], 60);
		assert.equal(outcome.timedOut, true, JSON.stringify(result));
		assert.equal(outcome.ok, false);
	}
});

test("a clean stryker run is neither failed nor timed out", () => {
	const outcome = makeRunStryker(() => OK)("/repo", ["src/a.ts:1:1-2:1"], 60);
	assert.equal(outcome.ok, true);
	assert.equal(outcome.timedOut, false);
});

test("stryker failure keeps only the tail of its stderr", () => {
	const stderr = ["line one", "line two", "line three", "line four", "line five"].join("\n");
	const outcome = makeRunStryker(() => ({ status: 1, stdout: "", stderr }))("/repo", [], 60);
	assert.equal(outcome.ok, false);
	assert.equal(outcome.detail, "line three\nline four\nline five");
});

test("the timeout is passed through to exec in milliseconds", () => {
	let seen: number | undefined;
	const outcome = makeRunStryker((_c, _a, opts) => {
		seen = opts.timeoutMs;
		return OK;
	})("/repo", [], 45);
	assert.equal(seen, 45_000, "seconds on the flag, milliseconds to the child");
	assert.equal(outcome.ok, true);
});

test/diff-ranges.test.ts.source:
import { test } from "node:test";
import assert from "node:assert/strict";
import {
	countLines,
	filterSourceRanges,
	mergeRanges,
	parseDiffRanges,
	toStrykerMutateArgs,
} from "../src/diff-ranges.ts";

test("parses a normal hunk into an inclusive range", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,3 +10,4 @@", "+one", "+two"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 10, end: 13 }]);
});

test("an omitted count means exactly one line", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10 +10 @@", "+one"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 10, end: 10 }]);
});

test("a new file yields a range covering the whole file", () => {
	const diff = ["--- /dev/null", "+++ b/src/new.ts", "@@ -0,0 +1,50 @@"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/new.ts", start: 1, end: 50 }]);
});

test("a pure deletion yields no range — nothing remains to mutate", () => {
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -10,5 +9,0 @@", "-gone"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("a deleted file yields no range", () => {
	const diff = ["--- a/src/gone.ts", "+++ /dev/null", "@@ -1,20 +0,0 @@"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("multiple files and hunks are all captured", () => {
	const diff = [
		"--- a/src/a.ts",
		"+++ b/src/a.ts",
		"@@ -1,0 +2,1 @@",
		"+x",
		"@@ -20,0 +30,3 @@",
		"+y",
		"--- a/src/b.ts",
		"+++ b/src/b.ts",
		"@@ -5,2 +5,2 @@",
		"+z",
	].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [
		{ file: "src/a.ts", start: 2, end: 2 },
		{ file: "src/a.ts", start: 30, end: 32 },
		{ file: "src/b.ts", start: 5, end: 6 },
	]);
});

test("hunks before any file header are ignored rather than misattributed", () => {
	const diff = ["@@ -1,2 +1,2 @@", "+orphan"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), []);
});

test("filters out test files and anything outside the source globs", () => {
	const ranges = [
		{ file: "src/a.ts", start: 1, end: 2 },
		{ file: "test/a.test.ts", start: 1, end: 2 },
		{ file: "docs/readme.md", start: 1, end: 2 },
	];
	const kept = filterSourceRanges(ranges, { include: [/^src\/.*\.ts$/], exclude: [/\.test\.ts$/] });
	assert.deepEqual(kept, [{ file: "src/a.ts", start: 1, end: 2 }]);
});

test("merges overlapping and abutting ranges, leaves separated ones alone", () => {
	const merged = mergeRanges([
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/a.ts", start: 13, end: 15 }, // abuts
		{ file: "src/a.ts", start: 14, end: 20 }, // overlaps
		{ file: "src/a.ts", start: 40, end: 41 }, // separate
	]);
	assert.deepEqual(merged, [
		{ file: "src/a.ts", start: 10, end: 20 },
		{ file: "src/a.ts", start: 40, end: 41 },
	]);
});

test("merging keeps files independent", () => {
	const merged = mergeRanges([
		{ file: "src/b.ts", start: 1, end: 2 },
		{ file: "src/a.ts", start: 1, end: 2 },
	]);
	assert.equal(merged.length, 2);
	assert.equal(merged[0].file, "src/a.ts");
});

test("stryker range syntax spans the line inclusively", () => {
	// Column 1 of the line after the range is what makes the last line inclusive.
	assert.deepEqual(toStrykerMutateArgs([{ file: "src/a.ts", start: 70, end: 89 }]), ["src/a.ts:70:1-90:1"]);
});

test("countLines is inclusive of both ends", () => {
	assert.equal(countLines([{ file: "a", start: 10, end: 10 }]), 1);
	assert.equal(countLines([{ file: "a", start: 1, end: 5 }, { file: "b", start: 1, end: 3 }]), 8);
});

// --- gaps found by mutation testing, not by review ---

test("a hunk header with multi-digit counts still parses", () => {
	// `(?:,\d+)?` losing its `+` narrows the old-count to one digit and the whole
	// header stops matching. Every earlier fixture used single-digit old counts,
	// so nothing caught it.
	const diff = ["--- a/src/a.ts", "+++ b/src/a.ts", "@@ -100,25 +200,30 @@", "+x"].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/a.ts", start: 200, end: 229 }]);
});

test("a deleted file clears the current file rather than inheriting it", () => {
	// Without matching `+++ /dev/null`, `file` stays pointed at the previous entry
	// and the deleted file's hunks are attributed to it.
	const diff = [
		"--- a/src/kept.ts",
		"+++ b/src/kept.ts",
		"@@ -1,0 +5,2 @@",
		"+x",
		"--- a/src/gone.ts",
		"+++ /dev/null",
		"@@ -1,20 +0,0 @@",
	].join("\n");
	assert.deepEqual(parseDiffRanges(diff), [{ file: "src/kept.ts", start: 5, end: 6 }]);
});

test("include is an any-match, not an all-match", () => {
	// With a single include pattern `some` and `every` behave identically, so a
	// second pattern is what proves the intent.
	const ranges = [{ file: "src/a.ts", start: 1, end: 2 }];
	const kept = filterSourceRanges(ranges, { include: [/^lib\//, /^src\//], exclude: [] });
	assert.deepEqual(kept, ranges, "matching any one include pattern is enough");
});

test("exclude is an any-match: one matching pattern is enough to drop a file", () => {
	const ranges = [{ file: "src/a.test.ts", start: 1, end: 2 }];
	const kept = filterSourceRanges(ranges, {
		include: [/^src\//],
		exclude: [/\.test\.ts$/, /^vendor\//],
	});
	assert.deepEqual(kept, [], "matching one exclude pattern drops it, not all of them");
});

test("ranges arriving out of order are sorted before merging", () => {
	// Earlier fixtures were already ordered, so removing the comparator changed
	// nothing and the mutant lived.
	const merged = mergeRanges([
		{ file: "src/a.ts", start: 40, end: 41 },
		{ file: "src/a.ts", start: 10, end: 12 },
		{ file: "src/a.ts", start: 13, end: 15 },
	]);
	assert.deepEqual(merged, [
		{ file: "src/a.ts", start: 10, end: 15 },
		{ file: "src/a.ts", start: 40, end: 41 },
	]);
});

test/cli.test.ts.source:
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { main, mtok, run, type Io } from "../src/cli.ts";
import type { PriceTable } from "../src/pricing.ts";

/**
 * The CLI reaches for `process` for output, exit codes, cwd and the clock. All of
 * it is injected here so a command that rejects bad input can be asserted on
 * instead of taking the test runner down with it.
 *
 * An empty price table by default: notional pricing must not depend on whatever
 * happens to be in this machine's pi model registry.
 */
function harness(prices: PriceTable = new Map()) {
	const dir = mkdtempSync(join(tmpdir(), "craft-cli-"));
	const out: string[] = [];
	const err: string[] = [];
	const io: Io = {
		write: (s) => out.push(s),
		error: (s) => err.push(s),
		cwd: () => "/tmp/project",
		now: () => Date.parse("2026-04-08T12:00:00.000Z"),
		storePath: () => join(dir, "events.jsonl"),
		prices,
	};
	return {
		io,
		out: () => out.join(""),
		err: () => err.join(""),
		events: () => {
			try {
				return readFileSync(join(dir, "events.jsonl"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
			} catch {
				return [];
			}
		},
		cleanup: () => rmSync(dir, { recursive: true, force: true }),
	};
}

test("no command prints usage and succeeds", () => {
	const h = harness();
	try {
		assert.equal(main([], h.io), 0);
		assert.match(h.out(), /^craft-metrics —/);
	} finally {
		h.cleanup();
	}
});

test("--help and -h both print usage", () => {
	for (const flag of ["--help", "-h"]) {
		const h = harness();
		try {
			assert.equal(main([flag], h.io), 0);
			assert.match(h.out(), /Usage:/);
		} finally {
			h.cleanup();
		}
	}
});

test("an unknown command exits 2 and shows usage", () => {
	const h = harness();
	try {
		assert.equal(main(["frobnicate"], h.io), 2);
		assert.match(h.err(), /unknown command frobnicate/);
		assert.match(h.out(), /Usage:/);
	} finally {
		h.cleanup();
	}
});

test("start writes a run and echoes its id", () => {
	const h = harness();
	try {
		assert.equal(main(["start", "--kind", "feature", "--mode", "full"], h.io), 0);
		const id = h.out().trim();
		assert.match(id, /^[0-9a-f-]{36}$/);
		const opened = h.events().find((e) => e.t === "run_open");
		assert.equal(opened.kind, "feature");
		assert.equal(opened.mode, "full");
		// cwd and repo both fall back to the injected working directory.
		assert.equal(opened.cwd, "/tmp/project");
		assert.equal(opened.repo, "project");
	} finally {
		h.cleanup();
	}
});

