		for (const cwd of ["/tmp/a", "/tmp/b", "/tmp/c"]) {
			main(["start", "--kind", "feature", "--mode", "full", "--cwd", cwd], h.io);
			ids.push(h.out().trim().split("\n").at(-1)!);
		}
		const before = h.out().length;
		main(["show", "--last", "1"], h.io);
